<template><div><input v-model.number='amount' type='number'/><button @click='transfer'>Transfer 100</button><p>Amount: {{amount}}</p></div></template><script setup>import {ref} from 'vue';import {useBankStore} from '../stores/bankStore';const store=useBankStore();const amount=ref(100);function transfer(){store.accounts[0].balance-=amount.value;store.accounts[1].balance+=amount.value;}</script>